import rti.connextdds as dds
import rti.types as idl
from rti.rpc import Requester
import json, time, argparse

# 1. Define request/reply types with @idl.struct
@idl.struct(
    member_annotations={
        'operation': [idl.bound(64)],
    }
)
class MyRequest:
    operation: str = ""
    x: int = 0
    y: int = 0

@idl.struct(
    member_annotations={
        'error': [idl.bound(256)],
    }
)
class MyReply:
    result: int = 0
    success: bool = False
    error: str = ""

# 2. Create participant and requester
participant = dds.DomainParticipant(0)
requester = Requester(
    request_type=MyRequest,
    reply_type=MyReply,
    participant=participant,
    service_name="MyService"
)

# 3. Wait for service discovery
start = time.time()
while requester.matched_replier_count == 0:
    if time.time() - start > 5:
        print(json.dumps({"result": 0, "success": False, "error": "Service not found"}))
        exit(1)
    time.sleep(0.1)

# 4. Send request and receive reply
request = MyRequest(operation="add", x=10, y=5)
request_id = requester.send_request(request)

try:
    replies = requester.receive_replies(
        max_wait=dds.Duration(seconds=5),
        related_request_id=request_id
    )
except dds.TimeoutError:
    print(json.dumps({"result": 0, "success": False, "error": "No reply received"}))
    exit(1)

if len(replies) > 0 and replies[0].info.valid:
    reply = replies[0].data
    print(json.dumps({"result": reply.result, "success": reply.success}))
else:
    print(json.dumps({"result": 0, "success": False, "error": "Invalid reply"}))

